// Update function
function update(time) {
  // Calculate angular acceleration
  a = (-G / L) * Math.sin(theta);

  // Update angular velocity
  omega += a * (time - lastTime) / 1000;
  lastTime = time;

  // Update angle
  theta += omega * (time - lastTime) / 1000;
  theta = Math.min(Math.max(theta, -Math.PI / 2), Math.PI / 2);

